window.INSPIRATION_THEMES = {"1": "New Beginnings", "2": "Loved by God", "3": "Trust in the Lord", "4": "Strength & Courage", "5": "A Life of Prayer", "6": "The Peace of God", "7": "Walk by Faith", "8": "Thy Word Is a Lamp", "9": "God Is Faithful", "10": "Hope That Holds", "11": "Give Thanks", "12": "Unto Us a Child Is Born"};
window.INSPIRATIONS = {"1-1": {"v": "In the beginning God created the heaven and the earth.", "r": "Genesis 1:1"}, "1-2": {"v": "Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.", "r": "Isaiah 43:19"}, "1-3": {"v": "They are new every morning: great is thy faithfulness.", "r": "Lamentations 3:23"}, "1-4": {"v": "Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.", "r": "2 Corinthians 5:17"}, "1-5": {"v": "And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful.", "r": "Revelation 21:5"}, "1-6": {"v": "A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.", "r": "Ezekiel 36:26"}, "1-7": {"v": "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.", "r": "Isaiah 40:31"}, "1-8": {"v": "Create in me a clean heart, O God; and renew a right spirit within me.", "r": "Psalm 51:10"}, "1-9": {"v": "Therefore we are buried with him by baptism into death: that like as Christ was raised up from the dead by the glory of the Father, even so we also should walk in newness of life.", "r": "Romans 6:4"}, "1-10": {"v": "And have put on the new man, which is renewed in knowledge after the image of him that created him:", "r": "Colossians 3:10"}, "1-11": {"v": "And that ye put on the new man, which after God is created in righteousness and true holiness.", "r": "Ephesians 4:24"}, "1-12": {"v": "For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.", "r": "Jeremiah 29:11"}, "1-13": {"v": "I press toward the mark for the prize of the high calling of God in Christ Jesus.", "r": "Philippians 3:14"}, "1-14": {"v": "For, behold, I create new heavens and a new earth: and the former shall not be remembered, nor come into mind.", "r": "Isaiah 65:17"}, "1-15": {"v": "Thou crownest the year with thy goodness; and thy paths drop fatness.", "r": "Psalm 65:11"}, "1-16": {"v": "And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.", "r": "Deuteronomy 31:8"}, "1-17": {"v": "Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,", "r": "Hebrews 12:1"}, "1-18": {"v": "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.", "r": "Revelation 21:4"}, "1-19": {"v": "To appoint unto them that mourn in Zion, to give unto them beauty for ashes, the oil of joy for mourning, the garment of praise for the spirit of heaviness; that they might be called trees of righteousness, the planting of the LORD, that he might be glorified.", "r": "Isaiah 61:3"}, "1-20": {"v": "Cause me to hear thy lovingkindness in the morning; for in thee do I trust: cause me to know the way wherein I should walk; for I lift up my soul unto thee.", "r": "Psalm 143:8"}, "1-21": {"v": "But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:", "r": "John 1:12"}, "1-22": {"v": "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.", "r": "Romans 12:2"}, "1-23": {"v": "For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day.", "r": "2 Corinthians 4:16"}, "1-24": {"v": "This is the day which the LORD hath made; we will rejoice and be glad in it.", "r": "Psalm 118:24"}, "1-25": {"v": "And the LORD shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not.", "r": "Isaiah 58:11"}, "1-26": {"v": "He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?", "r": "Micah 6:8"}, "1-27": {"v": "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.", "r": "James 1:5"}, "1-28": {"v": "The steps of a good man are ordered by the LORD: and he delighteth in his way.", "r": "Psalm 37:23"}, "1-29": {"v": "And God said, Let there be light: and there was light.", "r": "Genesis 1:3"}, "1-30": {"v": "He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.", "r": "Ecclesiastes 3:11"}, "1-31": {"v": "Jesus Christ the same yesterday, and to day, and for ever.", "r": "Hebrews 13:8"}, "2-1": {"v": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.", "r": "John 3:16"}, "2-2": {"v": "But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.", "r": "Romans 5:8"}, "2-3": {"v": "He that loveth not knoweth not God; for God is love.", "r": "1 John 4:8"}, "2-4": {"v": "We love him, because he first loved us.", "r": "1 John 4:19"}, "2-5": {"v": "The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.", "r": "Jeremiah 31:3"}, "2-6": {"v": "The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.", "r": "Zephaniah 3:17"}, "2-7": {"v": "For as the heaven is high above the earth, so great is his mercy toward them that fear him.", "r": "Psalm 103:11"}, "2-8": {"v": "It is of the LORD'S mercies that we are not consumed, because his compassions fail not.", "r": "Lamentations 3:22"}, "2-9": {"v": "Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.", "r": "Romans 8:39"}, "2-10": {"v": "And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God.", "r": "Ephesians 3:19"}, "2-11": {"v": "How excellent is thy lovingkindness, O God! therefore the children of men put their trust under the shadow of thy wings.", "r": "Psalm 36:7"}, "2-12": {"v": "Because thy lovingkindness is better than life, my lips shall praise thee.", "r": "Psalm 63:3"}, "2-13": {"v": "For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the LORD that hath mercy on thee.", "r": "Isaiah 54:10"}, "2-14": {"v": "Greater love hath no man than this, that a man lay down his life for his friends.", "r": "John 15:13"}, "2-15": {"v": "Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,", "r": "1 Corinthians 13:4"}, "2-16": {"v": "And now abideth faith, hope, charity, these three; but the greatest of these is charity.", "r": "1 Corinthians 13:13"}, "2-17": {"v": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.", "r": "Galatians 2:20"}, "2-18": {"v": "And walk in love, as Christ also hath loved us, and hath given himself for us an offering and a sacrifice to God for a sweetsmelling savour.", "r": "Ephesians 5:2"}, "2-19": {"v": "Yet the LORD will command his lovingkindness in the daytime, and in the night his song shall be with me, and my prayer unto the God of my life.", "r": "Psalm 42:8"}, "2-20": {"v": "O give thanks unto the LORD; for he is good: for his mercy endureth for ever.", "r": "Psalm 136:1"}, "2-21": {"v": "Casting all your care upon him; for he careth for you.", "r": "1 Peter 5:7"}, "2-22": {"v": "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.", "r": "John 13:34"}, "2-23": {"v": "Love worketh no ill to his neighbour: therefore love is the fulfilling of the law.", "r": "Romans 13:10"}, "2-24": {"v": "And above all these things put on charity, which is the bond of perfectness.", "r": "Colossians 3:14"}, "2-25": {"v": "Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.", "r": "1 John 3:1"}, "2-26": {"v": "For his merciful kindness is great toward us: and the truth of the LORD endureth for ever. Praise ye the LORD.", "r": "Psalm 117:2"}, "2-27": {"v": "Keep yourselves in the love of God, looking for the mercy of our Lord Jesus Christ unto eternal life.", "r": "Jude 1:21"}, "2-28": {"v": "Know therefore that the LORD thy God, he is God, the faithful God, which keepeth covenant and mercy with them that love him and keep his commandments to a thousand generations;", "r": "Deuteronomy 7:9"}, "3-1": {"v": "Trust in the LORD with all thine heart; and lean not unto thine own understanding.", "r": "Proverbs 3:5"}, "3-2": {"v": "In all thy ways acknowledge him, and he shall direct thy paths.", "r": "Proverbs 3:6"}, "3-3": {"v": "What time I am afraid, I will trust in thee.", "r": "Psalm 56:3"}, "3-4": {"v": "Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah.", "r": "Psalm 62:8"}, "3-5": {"v": "In God have I put my trust: I will not be afraid what man can do unto me.", "r": "Psalm 56:11"}, "3-6": {"v": "Behold, God is my salvation; I will trust, and not be afraid: for the LORD JEHOVAH is my strength and my song; he also is become my salvation.", "r": "Isaiah 12:2"}, "3-7": {"v": "Commit thy way unto the LORD; trust also in him; and he shall bring it to pass.", "r": "Psalm 37:5"}, "3-8": {"v": "I will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.", "r": "Psalm 91:2"}, "3-9": {"v": "The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him.", "r": "Nahum 1:7"}, "3-10": {"v": "It is better to trust in the LORD than to put confidence in man.", "r": "Psalm 118:8"}, "3-11": {"v": "Blessed is the man that trusteth in the LORD, and whose hope the LORD is.", "r": "Jeremiah 17:7"}, "3-12": {"v": "Blessed is that man that maketh the LORD his trust, and respecteth not the proud, nor such as turn aside to lies.", "r": "Psalm 40:4"}, "3-13": {"v": "Many sorrows shall be to the wicked: but he that trusteth in the LORD, mercy shall compass him about.", "r": "Psalm 32:10"}, "3-14": {"v": "Who is among you that feareth the LORD, that obeyeth the voice of his servant, that walketh in darkness, and hath no light? let him trust in the name of the LORD, and stay upon his God.", "r": "Isaiah 50:10"}, "3-15": {"v": "A Song of degrees. They that trust in the LORD shall be as mount Zion, which cannot be removed, but abideth for ever.", "r": "Psalm 125:1"}, "3-16": {"v": "As for God, his way is perfect: the word of the LORD is tried: he is a buckler to all those that trust in him.", "r": "Psalm 18:30"}, "3-17": {"v": "O LORD of hosts, blessed is the man that trusteth in thee.", "r": "Psalm 84:12"}, "3-18": {"v": "He that handleth a matter wisely shall find good: and whoso trusteth in the LORD, happy is he.", "r": "Proverbs 16:20"}, "3-19": {"v": "The fear of man bringeth a snare: but whoso putteth his trust in the LORD shall be safe.", "r": "Proverbs 29:25"}, "3-20": {"v": "But I have trusted in thy mercy; my heart shall rejoice in thy salvation.", "r": "Psalm 13:5"}, "3-21": {"v": "Though he slay me, yet will I trust in him: but I will maintain mine own ways before him.", "r": "Job 13:15"}, "3-22": {"v": "And they that know thy name will put their trust in thee: for thou, LORD, hast not forsaken them that seek thee.", "r": "Psalm 9:10"}, "3-23": {"v": "But I trusted in thee, O LORD: I said, Thou art my God.", "r": "Psalm 31:14"}, "3-24": {"v": "Trust ye in the LORD for ever: for in the LORD JEHOVAH is everlasting strength:", "r": "Isaiah 26:4"}, "3-25": {"v": "Ye that fear the LORD, trust in the LORD: he is their help and their shield.", "r": "Psalm 115:11"}, "3-26": {"v": "If it be so, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver us out of thine hand, O king.", "r": "Daniel 3:17"}, "3-27": {"v": "Yet I will rejoice in the LORD, I will joy in the God of my salvation.", "r": "Habakkuk 3:18"}, "3-28": {"v": "But I am like a green olive tree in the house of God: I trust in the mercy of God for ever and ever.", "r": "Psalm 52:8"}, "3-29": {"v": "As soon as Jesus heard the word that was spoken, he saith unto the ruler of the synagogue, Be not afraid, only believe.", "r": "Mark 5:36"}, "3-30": {"v": "Let not your heart be troubled: ye believe in God, believe also in me.", "r": "John 14:1"}, "3-31": {"v": "Wait on the LORD: be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD.", "r": "Psalm 27:14"}, "4-1": {"v": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.", "r": "Joshua 1:9"}, "4-2": {"v": "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.", "r": "Isaiah 41:10"}, "4-3": {"v": "To the chief Musician for the sons of Korah, A Song upon Alamoth. God is our refuge and strength, a very present help in trouble.", "r": "Psalm 46:1"}, "4-4": {"v": "Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.", "r": "Deuteronomy 31:6"}, "4-5": {"v": "A Psalm of David. The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?", "r": "Psalm 27:1"}, "4-6": {"v": "He giveth power to the faint; and to them that have no might he increaseth strength.", "r": "Isaiah 40:29"}, "4-7": {"v": "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength.", "r": "Nehemiah 8:10"}, "4-8": {"v": "I can do all things through Christ which strengtheneth me.", "r": "Philippians 4:13"}, "4-9": {"v": "Finally, my brethren, be strong in the Lord, and in the power of his might.", "r": "Ephesians 6:10"}, "4-10": {"v": "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.", "r": "2 Timothy 1:7"}, "4-11": {"v": "Watch ye, stand fast in the faith, quit you like men, be strong.", "r": "1 Corinthians 16:13"}, "4-12": {"v": "And David said to Solomon his son, Be strong and of good courage, and do it: fear not, nor be dismayed: for the LORD God, even my God, will be with thee; he will not fail thee, nor forsake thee, until thou hast finished all the work for the service of the house of the LORD.", "r": "1 Chronicles 28:20"}, "4-13": {"v": "Say to them that are of a fearful heart, Be strong, fear not: behold, your God will come with vengeance, even God with a recompence; he will come and save you.", "r": "Isaiah 35:4"}, "4-14": {"v": "The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father's God, and I will exalt him.", "r": "Exodus 15:2"}, "4-15": {"v": "Be ye strong therefore, and let not your hands be weak: for your work shall be rewarded.", "r": "2 Chronicles 15:7"}, "4-16": {"v": "Yet now be strong, O Zerubbabel, saith the LORD; and be strong, O Joshua, son of Josedech, the high priest; and be strong, all ye people of the land, saith the LORD, and work: for I am with you, saith the LORD of hosts:", "r": "Haggai 2:4"}, "4-17": {"v": "Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.", "r": "Zechariah 4:6"}, "4-18": {"v": "And said, O man greatly beloved, fear not: peace be unto thee, be strong, yea, be strong. And when he had spoken unto me, I was strengthened, and said, Let my lord speak; for thou hast strengthened me.", "r": "Daniel 10:19"}, "4-19": {"v": "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.", "r": "Psalm 73:26"}, "4-20": {"v": "The LORD God is my strength, and he will make my feet like hinds' feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments.", "r": "Habakkuk 3:19"}, "4-21": {"v": "In the day when I cried thou answeredst me, and strengthenedst me with strength in my soul.", "r": "Psalm 138:3"}, "4-22": {"v": "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.", "r": "2 Corinthians 12:9"}, "4-23": {"v": "What shall we then say to these things? If God be for us, who can be against us?", "r": "Romans 8:31"}, "4-24": {"v": "The LORD is on my side; I will not fear: what can man do unto me?", "r": "Psalm 118:6"}, "4-25": {"v": "So that we may boldly say, The Lord is my helper, and I will not fear what man shall do unto me.", "r": "Hebrews 13:6"}, "4-26": {"v": "Beat your plowshares into swords, and your pruninghooks into spears: let the weak say, I am strong.", "r": "Joel 3:10"}, "4-27": {"v": "It is God that girdeth me with strength, and maketh my way perfect.", "r": "Psalm 18:32"}, "4-28": {"v": "For I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.", "r": "Isaiah 41:13"}, "4-29": {"v": "The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.", "r": "Psalm 28:7"}, "4-30": {"v": "God is my strength and power: and he maketh my way perfect.", "r": "2 Samuel 22:33"}, "5-1": {"v": "But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly.", "r": "Matthew 6:6"}, "5-2": {"v": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.", "r": "Philippians 4:6"}, "5-3": {"v": "Pray without ceasing.", "r": "1 Thessalonians 5:17"}, "5-4": {"v": "Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.", "r": "James 5:16"}, "5-5": {"v": "Evening, and morning, and at noon, will I pray, and cry aloud: and he shall hear my voice.", "r": "Psalm 55:17"}, "5-6": {"v": "Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.", "r": "Mark 11:24"}, "5-7": {"v": "If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you.", "r": "John 15:7"}, "5-8": {"v": "Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.", "r": "Romans 8:26"}, "5-9": {"v": "Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.", "r": "Hebrews 4:16"}, "5-10": {"v": "Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.", "r": "Jeremiah 33:3"}, "5-11": {"v": "The righteous cry, and the LORD heareth, and delivereth them out of all their troubles.", "r": "Psalm 34:17"}, "5-12": {"v": "The LORD is nigh unto all them that call upon him, to all that call upon him in truth.", "r": "Psalm 145:18"}, "5-13": {"v": "And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:", "r": "1 John 5:14"}, "5-14": {"v": "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:", "r": "Matthew 7:7"}, "5-15": {"v": "And he spake a parable unto them to this end, that men ought always to pray, and not to faint;", "r": "Luke 18:1"}, "5-16": {"v": "Continue in prayer, and watch in the same with thanksgiving;", "r": "Colossians 4:2"}, "5-17": {"v": "Praying always with all prayer and supplication in the Spirit, and watching thereunto with all perseverance and supplication for all saints;", "r": "Ephesians 6:18"}, "5-18": {"v": "My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up.", "r": "Psalm 5:3"}, "5-19": {"v": "Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime.", "r": "Daniel 6:10"}, "5-20": {"v": "If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.", "r": "2 Chronicles 7:14"}, "5-21": {"v": "And it shall come to pass, that before they call, I will answer; and while they are yet speaking, I will hear.", "r": "Isaiah 65:24"}, "5-22": {"v": "And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.", "r": "Matthew 21:22"}, "5-23": {"v": "For the eyes of the Lord are over the righteous, and his ears are open unto their prayers: but the face of the Lord is against them that do evil.", "r": "1 Peter 3:12"}, "5-24": {"v": "The sacrifice of the wicked is an abomination to the LORD: but the prayer of the upright is his delight.", "r": "Proverbs 15:8"}, "5-25": {"v": "And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you.", "r": "Luke 11:9"}, "5-26": {"v": "Rejoicing in hope; patient in tribulation; continuing instant in prayer;", "r": "Romans 12:12"}, "5-27": {"v": "I have called upon thee, for thou wilt hear me, O God: incline thine ear unto me, and hear my speech.", "r": "Psalm 17:6"}, "5-28": {"v": "Let my prayer be set forth before thee as incense; and the lifting up of my hands as the evening sacrifice.", "r": "Psalm 141:2"}, "5-29": {"v": "Blessed be God, which hath not turned away my prayer, nor his mercy from me.", "r": "Psalm 66:20"}, "5-30": {"v": "He will regard the prayer of the destitute, and not despise their prayer.", "r": "Psalm 102:17"}, "5-31": {"v": "When my soul fainted within me I remembered the LORD: and my prayer came in unto thee, into thine holy temple.", "r": "Jonah 2:7"}, "6-1": {"v": "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.", "r": "John 14:27"}, "6-2": {"v": "And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.", "r": "Philippians 4:7"}, "6-3": {"v": "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.", "r": "Isaiah 26:3"}, "6-4": {"v": "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.", "r": "Colossians 3:15"}, "6-5": {"v": "The LORD will give strength unto his people; the LORD will bless his people with peace.", "r": "Psalm 29:11"}, "6-6": {"v": "I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.", "r": "Psalm 4:8"}, "6-7": {"v": "The LORD lift up his countenance upon thee, and give thee peace.", "r": "Numbers 6:26"}, "6-8": {"v": "These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.", "r": "John 16:33"}, "6-9": {"v": "Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:", "r": "Romans 5:1"}, "6-10": {"v": "Now the Lord of peace himself give you peace always by all means. The Lord be with you all.", "r": "2 Thessalonians 3:16"}, "6-11": {"v": "Peace be within thy walls, and prosperity within thy palaces.", "r": "Psalm 122:7"}, "6-12": {"v": "And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever.", "r": "Isaiah 32:17"}, "6-13": {"v": "And all thy children shall be taught of the LORD; and great shall be the peace of thy children.", "r": "Isaiah 54:13"}, "6-14": {"v": "When a man's ways please the LORD, he maketh even his enemies to be at peace with him.", "r": "Proverbs 16:7"}, "6-15": {"v": "I create the fruit of the lips; Peace, peace to him that is far off, and to him that is near, saith the LORD; and I will heal him.", "r": "Isaiah 57:19"}, "6-16": {"v": "Acquaint now thyself with him, and be at peace: thereby good shall come unto thee.", "r": "Job 22:21"}, "6-17": {"v": "Great peace have they which love thy law: and nothing shall offend them.", "r": "Psalm 119:165"}, "6-18": {"v": "Blessed are the peacemakers: for they shall be called the children of God.", "r": "Matthew 5:9"}, "6-19": {"v": "Let us therefore follow after the things which make for peace, and things wherewith one may edify another.", "r": "Romans 14:19"}, "6-20": {"v": "Depart from evil, and do good; seek peace, and pursue it.", "r": "Psalm 34:14"}, "6-21": {"v": "O that thou hadst hearkened to my commandments! then had thy peace been as a river, and thy righteousness as the waves of the sea:", "r": "Isaiah 48:18"}, "6-22": {"v": "For thus saith the LORD, Behold, I will extend peace to her like a river, and the glory of the Gentiles like a flowing stream: then shall ye suck, ye shall be borne upon her sides, and be dandled upon her knees.", "r": "Isaiah 66:12"}, "6-23": {"v": "For to be carnally minded is death; but to be spiritually minded is life and peace.", "r": "Romans 8:6"}, "6-24": {"v": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,", "r": "Galatians 5:22"}, "6-25": {"v": "For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us;", "r": "Ephesians 2:14"}, "6-26": {"v": "Now the God of peace be with you all. Amen.", "r": "Romans 15:33"}, "6-27": {"v": "I will hear what God the LORD will speak: for he will speak peace unto his people, and to his saints: but let them not turn again to folly.", "r": "Psalm 85:8"}, "6-28": {"v": "How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!", "r": "Isaiah 52:7"}, "6-29": {"v": "Follow peace with all men, and holiness, without which no man shall see the Lord:", "r": "Hebrews 12:14"}, "6-30": {"v": "And the fruit of righteousness is sown in peace of them that make peace.", "r": "James 3:18"}, "7-1": {"v": "Now faith is the substance of things hoped for, the evidence of things not seen.", "r": "Hebrews 11:1"}, "7-2": {"v": "But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.", "r": "Hebrews 11:6"}, "7-3": {"v": "So then faith cometh by hearing, and hearing by the word of God.", "r": "Romans 10:17"}, "7-4": {"v": "(For we walk by faith, not by sight:)", "r": "2 Corinthians 5:7"}, "7-5": {"v": "And Jesus answering saith unto them, Have faith in God.", "r": "Mark 11:22"}, "7-6": {"v": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:", "r": "Ephesians 2:8"}, "7-7": {"v": "That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ:", "r": "1 Peter 1:7"}, "7-8": {"v": "Knowing this, that the trying of your faith worketh patience.", "r": "James 1:3"}, "7-9": {"v": "For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith.", "r": "Romans 1:17"}, "7-10": {"v": "Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith.", "r": "Habakkuk 2:4"}, "7-11": {"v": "And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.", "r": "Matthew 17:20"}, "7-12": {"v": "And the Lord said, If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you.", "r": "Luke 17:6"}, "7-13": {"v": "Jesus said unto him, If thou canst believe, all things are possible to him that believeth.", "r": "Mark 9:23"}, "7-14": {"v": "Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.", "r": "John 20:29"}, "7-15": {"v": "And being fully persuaded that, what he had promised, he was able also to perform.", "r": "Romans 4:21"}, "7-16": {"v": "Now the just shall live by faith: but if any man draw back, my soul shall have no pleasure in him.", "r": "Hebrews 10:38"}, "7-17": {"v": "Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.", "r": "Hebrews 12:2"}, "7-18": {"v": "That your faith should not stand in the wisdom of men, but in the power of God.", "r": "1 Corinthians 2:5"}, "7-19": {"v": "For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith.", "r": "1 John 5:4"}, "7-20": {"v": "But ye, beloved, building up yourselves on your most holy faith, praying in the Holy Ghost,", "r": "Jude 1:20"}, "7-21": {"v": "I have fought a good fight, I have finished my course, I have kept the faith:", "r": "2 Timothy 4:7"}, "7-22": {"v": "And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.", "r": "Acts 16:31"}, "7-23": {"v": "And he said unto her, Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague.", "r": "Mark 5:34"}, "7-24": {"v": "Then touched he their eyes, saying, According to your faith be it unto you.", "r": "Matthew 9:29"}, "7-25": {"v": "Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked.", "r": "Ephesians 6:16"}, "7-26": {"v": "Fight the good fight of faith, lay hold on eternal life, whereunto thou art also called, and hast professed a good profession before many witnesses.", "r": "1 Timothy 6:12"}, "7-27": {"v": "But let him ask in faith, nothing wavering. For he that wavereth is like a wave of the sea driven with the wind and tossed.", "r": "James 1:6"}, "7-28": {"v": "I believed, therefore have I spoken: I was greatly afflicted:", "r": "Psalm 116:10"}, "7-29": {"v": "For in Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love.", "r": "Galatians 5:6"}, "7-30": {"v": "We having the same spirit of faith, according as it is written, I believed, and therefore have I spoken; we also believe, and therefore speak;", "r": "2 Corinthians 4:13"}, "7-31": {"v": "Remembering without ceasing your work of faith, and labour of love, and patience of hope in our Lord Jesus Christ, in the sight of God and our Father;", "r": "1 Thessalonians 1:3"}, "8-1": {"v": "NUN. Thy word is a lamp unto my feet, and a light unto my path.", "r": "Psalm 119:105"}, "8-2": {"v": "Thy word have I hid in mine heart, that I might not sin against thee.", "r": "Psalm 119:11"}, "8-3": {"v": "The entrance of thy words giveth light; it giveth understanding unto the simple.", "r": "Psalm 119:130"}, "8-4": {"v": "This book of the law shall not depart out of thy mouth; but thou shalt meditate therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success.", "r": "Joshua 1:8"}, "8-5": {"v": "All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:", "r": "2 Timothy 3:16"}, "8-6": {"v": "For the word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart.", "r": "Hebrews 4:12"}, "8-7": {"v": "The grass withereth, the flower fadeth: but the word of our God shall stand for ever.", "r": "Isaiah 40:8"}, "8-8": {"v": "Heaven and earth shall pass away, but my words shall not pass away.", "r": "Matthew 24:35"}, "8-9": {"v": "Sanctify them through thy truth: thy word is truth.", "r": "John 17:17"}, "8-10": {"v": "The statutes of the LORD are right, rejoicing the heart: the commandment of the LORD is pure, enlightening the eyes.", "r": "Psalm 19:8"}, "8-11": {"v": "But his delight is in the law of the LORD; and in his law doth he meditate day and night.", "r": "Psalm 1:2"}, "8-12": {"v": "And he humbled thee, and suffered thee to hunger, and fed thee with manna, which thou knewest not, neither did thy fathers know; that he might make thee know that man doth not live by bread only, but by every word that proceedeth out of the mouth of the LORD doth man live.", "r": "Deuteronomy 8:3"}, "8-13": {"v": "Thy words were found, and I did eat them; and thy word was unto me the joy and rejoicing of mine heart: for I am called by thy name, O LORD God of hosts.", "r": "Jeremiah 15:16"}, "8-14": {"v": "Neither have I gone back from the commandment of his lips; I have esteemed the words of his mouth more than my necessary food.", "r": "Job 23:12"}, "8-15": {"v": "LAMED. For ever, O LORD, thy word is settled in heaven.", "r": "Psalm 119:89"}, "8-16": {"v": "Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever.", "r": "Psalm 119:160"}, "8-17": {"v": "Every word of God is pure: he is a shield unto them that put their trust in him.", "r": "Proverbs 30:5"}, "8-18": {"v": "So shall my word be that goeth forth out of my mouth: it shall not return unto me void, but it shall accomplish that which I please, and it shall prosper in the thing whereto I sent it.", "r": "Isaiah 55:11"}, "8-19": {"v": "But he said, Yea rather, blessed are they that hear the word of God, and keep it.", "r": "Luke 11:28"}, "8-20": {"v": "But be ye doers of the word, and not hearers only, deceiving your own selves.", "r": "James 1:22"}, "8-21": {"v": "For whatsoever things were written aforetime were written for our learning, that we through patience and comfort of the scriptures might have hope.", "r": "Romans 15:4"}, "8-22": {"v": "In the beginning was the Word, and the Word was with God, and the Word was God.", "r": "John 1:1"}, "8-23": {"v": "And ye shall know the truth, and the truth shall make you free.", "r": "John 8:32"}, "8-24": {"v": "Open thou mine eyes, that I may behold wondrous things out of thy law.", "r": "Psalm 119:18"}, "8-25": {"v": "Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart.", "r": "Psalm 119:34"}, "8-26": {"v": "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.", "r": "Colossians 3:16"}, "8-27": {"v": "As newborn babes, desire the sincere milk of the word, that ye may grow thereby:", "r": "1 Peter 2:2"}, "8-28": {"v": "This is my comfort in my affliction: for thy word hath quickened me.", "r": "Psalm 119:50"}, "8-29": {"v": "Thou art my hiding place and my shield: I hope in thy word.", "r": "Psalm 119:114"}, "8-30": {"v": "And now, brethren, I commend you to God, and to the word of his grace, which is able to build you up, and to give you an inheritance among all them which are sanctified.", "r": "Acts 20:32"}, "8-31": {"v": "I will worship toward thy holy temple, and praise thy name for thy lovingkindness and for thy truth: for thou hast magnified thy word above all thy name.", "r": "Psalm 138:2"}, "9-1": {"v": "God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?", "r": "Numbers 23:19"}, "9-2": {"v": "There failed not ought of any good thing which the LORD had spoken unto the house of Israel; all came to pass.", "r": "Joshua 21:45"}, "9-3": {"v": "Blessed be the LORD, that hath given rest unto his people Israel, according to all that he promised: there hath not failed one word of all his good promise, which he promised by the hand of Moses his servant.", "r": "1 Kings 8:56"}, "9-4": {"v": "Maschil of Ethan the Ezrahite. I will sing of the mercies of the LORD for ever: with my mouth will I make known thy faithfulness to all generations.", "r": "Psalm 89:1"}, "9-5": {"v": "Let us hold fast the profession of our faith without wavering; (for he is faithful that promised;)", "r": "Hebrews 10:23"}, "9-6": {"v": "If we believe not, yet he abideth faithful: he cannot deny himself.", "r": "2 Timothy 2:13"}, "9-7": {"v": "For the LORD is good; his mercy is everlasting; and his truth endureth to all generations.", "r": "Psalm 100:5"}, "9-8": {"v": "Which made heaven, and earth, the sea, and all that therein is: which keepeth truth for ever:", "r": "Psalm 146:6"}, "9-9": {"v": "And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you.", "r": "Isaiah 46:4"}, "9-10": {"v": "Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:", "r": "Isaiah 46:10"}, "9-11": {"v": "For I am the LORD, I change not; therefore ye sons of Jacob are not consumed.", "r": "Malachi 3:6"}, "9-12": {"v": "Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.", "r": "James 1:17"}, "9-13": {"v": "Behold, he that keepeth Israel shall neither slumber nor sleep.", "r": "Psalm 121:4"}, "9-14": {"v": "The LORD is thy keeper: the LORD is thy shade upon thy right hand.", "r": "Psalm 121:5"}, "9-15": {"v": "The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.", "r": "Psalm 121:8"}, "9-16": {"v": "Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?", "r": "Matthew 6:26"}, "9-17": {"v": "But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.", "r": "Matthew 6:33"}, "9-18": {"v": "But even the very hairs of your head are all numbered. Fear not therefore: ye are of more value than many sparrows.", "r": "Luke 12:7"}, "9-19": {"v": "Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee.", "r": "Isaiah 49:15"}, "9-20": {"v": "And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave thee, until I have done that which I have spoken to thee of.", "r": "Genesis 28:15"}, "9-21": {"v": "And he said, My presence shall go with thee, and I will give thee rest.", "r": "Exodus 33:14"}, "9-22": {"v": "A Psalm of David. The LORD is my shepherd; I shall not want.", "r": "Psalm 23:1"}, "9-23": {"v": "Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.", "r": "Psalm 23:6"}, "9-24": {"v": "For all the promises of God in him are yea, and in him Amen, unto the glory of God by us.", "r": "2 Corinthians 1:20"}, "9-25": {"v": "And we know that all things work together for good to them that love God, to them who are the called according to his purpose.", "r": "Romans 8:28"}, "9-26": {"v": "Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:", "r": "Philippians 1:6"}, "9-27": {"v": "Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.", "r": "Psalm 55:22"}, "9-28": {"v": "Thy mercy, O LORD, is in the heavens; and thy faithfulness reacheth unto the clouds.", "r": "Psalm 36:5"}, "9-29": {"v": "He is the Rock, his work is perfect: for all his ways are judgment: a God of truth and without iniquity, just and right is he.", "r": "Deuteronomy 32:4"}, "9-30": {"v": "God is faithful, by whom ye were called unto the fellowship of his Son Jesus Christ our Lord.", "r": "1 Corinthians 1:9"}, "10-1": {"v": "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.", "r": "Romans 15:13"}, "10-2": {"v": "And hope maketh not ashamed; because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us.", "r": "Romans 5:5"}, "10-3": {"v": "But if we hope for that we see not, then do we with patience wait for it.", "r": "Romans 8:25"}, "10-4": {"v": "And we desire that every one of you do shew the same diligence to the full assurance of hope unto the end:", "r": "Hebrews 6:11"}, "10-5": {"v": "Which hope we have as an anchor of the soul, both sure and stedfast, and which entereth into that within the veil;", "r": "Hebrews 6:19"}, "10-6": {"v": "Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,", "r": "1 Peter 1:3"}, "10-7": {"v": "To whom God would make known what is the riches of the glory of this mystery among the Gentiles; which is Christ in you, the hope of glory:", "r": "Colossians 1:27"}, "10-8": {"v": "For the hope which is laid up for you in heaven, whereof ye heard before in the word of the truth of the gospel;", "r": "Colossians 1:5"}, "10-9": {"v": "In hope of eternal life, which God, that cannot lie, promised before the world began;", "r": "Titus 1:2"}, "10-10": {"v": "Looking for that blessed hope, and the glorious appearing of the great God and our Saviour Jesus Christ;", "r": "Titus 2:13"}, "10-11": {"v": "That being justified by his grace, we should be made heirs according to the hope of eternal life.", "r": "Titus 3:7"}, "10-12": {"v": "But Christ as a son over his own house; whose house are we, if we hold fast the confidence and the rejoicing of the hope firm unto the end.", "r": "Hebrews 3:6"}, "10-13": {"v": "For the law made nothing perfect, but the bringing in of a better hope did; by the which we draw nigh unto God.", "r": "Hebrews 7:19"}, "10-14": {"v": "Now our Lord Jesus Christ himself, and God, even our Father, which hath loved us, and hath given us everlasting consolation and good hope through grace,", "r": "2 Thessalonians 2:16"}, "10-15": {"v": "Be of good courage, and he shall strengthen your heart, all ye that hope in the LORD.", "r": "Psalm 31:24"}, "10-16": {"v": "Let thy mercy, O LORD, be upon us, according as we hope in thee.", "r": "Psalm 33:22"}, "10-17": {"v": "And now, Lord, what wait I for? my hope is in thee.", "r": "Psalm 39:7"}, "10-18": {"v": "Why art thou cast down, O my soul? and why art thou disquieted in me? hope thou in God: for I shall yet praise him for the help of his countenance.", "r": "Psalm 42:5"}, "10-19": {"v": "My soul, wait thou only upon God; for my expectation is from him.", "r": "Psalm 62:5"}, "10-20": {"v": "But I will hope continually, and will yet praise thee more and more.", "r": "Psalm 71:14"}, "10-21": {"v": "I wait for the LORD, my soul doth wait, and in his word do I hope.", "r": "Psalm 130:5"}, "10-22": {"v": "The LORD is my portion, saith my soul; therefore will I hope in him.", "r": "Lamentations 3:24"}, "10-23": {"v": "It is good that a man should both hope and quietly wait for the salvation of the LORD.", "r": "Lamentations 3:26"}, "10-24": {"v": "Therefore I will look unto the LORD; I will wait for the God of my salvation: my God will hear me.", "r": "Micah 7:7"}, "10-25": {"v": "And thou shalt be secure, because there is hope; yea, thou shalt dig about thee, and thou shalt take thy rest in safety.", "r": "Job 11:18"}, "10-26": {"v": "Happy is he that hath the God of Jacob for his help, whose hope is in the LORD his God:", "r": "Psalm 146:5"}, "10-27": {"v": "For surely there is an end; and thine expectation shall not be cut off.", "r": "Proverbs 23:18"}, "10-28": {"v": "Turn you to the strong hold, ye prisoners of hope: even to day do I declare that I will render double unto thee;", "r": "Zechariah 9:12"}, "10-29": {"v": "For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.", "r": "Romans 8:18"}, "10-30": {"v": "For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:", "r": "Philippians 3:20"}, "10-31": {"v": "Therefore my heart is glad, and my glory rejoiceth: my flesh also shall rest in hope.", "r": "Psalm 16:9"}, "11-1": {"v": "Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.", "r": "Psalm 100:4"}, "11-2": {"v": "O give thanks unto the God of heaven: for his mercy endureth for ever.", "r": "Psalm 136:26"}, "11-3": {"v": "O give thanks unto the LORD, for he is good: for his mercy endureth for ever.", "r": "Psalm 107:1"}, "11-4": {"v": "O give thanks unto the LORD; for he is good: for his mercy endureth for ever.", "r": "Psalm 118:29"}, "11-5": {"v": "Give thanks unto the LORD, call upon his name, make known his deeds among the people.", "r": "1 Chronicles 16:8"}, "11-6": {"v": "And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.", "r": "Colossians 3:17"}, "11-7": {"v": "In every thing give thanks: for this is the will of God in Christ Jesus concerning you.", "r": "1 Thessalonians 5:18"}, "11-8": {"v": "Rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving.", "r": "Colossians 2:7"}, "11-9": {"v": "Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms.", "r": "Psalm 95:2"}, "11-10": {"v": "I will praise the name of God with a song, and will magnify him with thanksgiving.", "r": "Psalm 69:30"}, "11-11": {"v": "I will offer to thee the sacrifice of thanksgiving, and will call upon the name of the LORD.", "r": "Psalm 116:17"}, "11-12": {"v": "Sing unto the LORD with thanksgiving; sing praise upon the harp unto our God:", "r": "Psalm 147:7"}, "11-13": {"v": "And in that day shall ye say, Praise the LORD, call upon his name, declare his doings among the people, make mention that his name is exalted.", "r": "Isaiah 12:4"}, "11-14": {"v": "For the LORD shall comfort Zion: he will comfort all her waste places; and he will make her wilderness like Eden, and her desert like the garden of the LORD; joy and gladness shall be found therein, thanksgiving, and the voice of melody.", "r": "Isaiah 51:3"}, "11-15": {"v": "But I will sacrifice unto thee with the voice of thanksgiving; I will pay that that I have vowed. Salvation is of the LORD.", "r": "Jonah 2:9"}, "11-16": {"v": "Thanks be unto God for his unspeakable gift.", "r": "2 Corinthians 9:15"}, "11-17": {"v": "Now thanks be unto God, which always causeth us to triumph in Christ, and maketh manifest the savour of his knowledge by us in every place.", "r": "2 Corinthians 2:14"}, "11-18": {"v": "But thanks be to God, which giveth us the victory through our Lord Jesus Christ.", "r": "1 Corinthians 15:57"}, "11-19": {"v": "Saying, Amen: Blessing, and glory, and wisdom, and thanksgiving, and honour, and power, and might, be unto our God for ever and ever. Amen.", "r": "Revelation 7:12"}, "11-20": {"v": "To the chief Musician upon Muthlabben, A Psalm of David. I will praise thee, O LORD, with my whole heart; I will shew forth all thy marvellous works.", "r": "Psalm 9:1"}, "11-21": {"v": "That I may publish with the voice of thanksgiving, and tell of all thy wondrous works.", "r": "Psalm 26:7"}, "11-22": {"v": "To the end that my glory may sing praise to thee, and not be silent. O LORD my God, I will give thanks unto thee for ever.", "r": "Psalm 30:12"}, "11-23": {"v": "I will give thee thanks in the great congregation: I will praise thee among much people.", "r": "Psalm 35:18"}, "11-24": {"v": "To the chief Musician, Altaschith, A Psalm or Song of Asaph. Unto thee, O God, do we give thanks, unto thee do we give thanks: for that thy name is near thy wondrous works declare.", "r": "Psalm 75:1"}, "11-25": {"v": "A Psalm or Song for the sabbath day. It is a good thing to give thanks unto the LORD, and to sing praises unto thy name, O most High:", "r": "Psalm 92:1"}, "11-26": {"v": "O give thanks unto the LORD; call upon his name: make known his deeds among the people.", "r": "Psalm 105:1"}, "11-27": {"v": "I thank thee, and praise thee, O thou God of my fathers, who hast given me wisdom and might, and hast made known unto me now what we desired of thee: for thou hast now made known unto us the king's matter.", "r": "Daniel 2:23"}, "11-28": {"v": "Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;", "r": "Ephesians 5:20"}, "11-29": {"v": "By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name.", "r": "Hebrews 13:15"}, "11-30": {"v": "What shall I render unto the LORD for all his benefits toward me?", "r": "Psalm 116:12"}, "12-1": {"v": "Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel.", "r": "Isaiah 7:14"}, "12-2": {"v": "But thou, Bethlehem Ephratah, though thou be little among the thousands of Judah, yet out of thee shall he come forth unto me that is to be ruler in Israel; whose goings forth have been from of old, from everlasting.", "r": "Micah 5:2"}, "12-3": {"v": "Arise, shine; for thy light is come, and the glory of the LORD is risen upon thee.", "r": "Isaiah 60:1"}, "12-4": {"v": "That was the true Light, which lighteth every man that cometh into the world.", "r": "John 1:9"}, "12-5": {"v": "But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall.", "r": "Malachi 4:2"}, "12-6": {"v": "I shall see him, but not now: I shall behold him, but not nigh: there shall come a Star out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth.", "r": "Numbers 24:17"}, "12-7": {"v": "And there shall come forth a rod out of the stem of Jesse, and a Branch shall grow out of his roots:", "r": "Isaiah 11:1"}, "12-8": {"v": "And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious.", "r": "Isaiah 11:10"}, "12-9": {"v": "Behold, the days come, saith the LORD, that I will raise unto David a righteous Branch, and a King shall reign and prosper, and shall execute judgment and justice in the earth.", "r": "Jeremiah 23:5"}, "12-10": {"v": "And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.", "r": "Daniel 7:14"}, "12-11": {"v": "The sceptre shall not depart from Judah, nor a lawgiver from between his feet, until Shiloh come; and unto him shall the gathering of the people be.", "r": "Genesis 49:10"}, "12-12": {"v": "And thine house and thy kingdom shall be established for ever before thee: thy throne shall be established for ever.", "r": "2 Samuel 7:16"}, "12-13": {"v": "Rejoice greatly, O daughter of Zion; shout, O daughter of Jerusalem: behold, thy King cometh unto thee: he is just, and having salvation; lowly, and riding upon an ass, and upon a colt the foal of an ass.", "r": "Zechariah 9:9"}, "12-14": {"v": "Blessed be the Lord God of Israel; for he hath visited and redeemed his people,", "r": "Luke 1:68"}, "12-15": {"v": "To give light to them that sit in darkness and in the shadow of death, to guide our feet into the way of peace.", "r": "Luke 1:79"}, "12-16": {"v": "The sun shall be no more thy light by day; neither for brightness shall the moon give light unto thee: but the LORD shall be unto thee an everlasting light, and thy God thy glory.", "r": "Isaiah 60:19"}, "12-17": {"v": "And she shall bring forth a son, and thou shalt call his name JESUS: for he shall save his people from their sins.", "r": "Matthew 1:21"}, "12-18": {"v": "Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us.", "r": "Matthew 1:23"}, "12-19": {"v": "And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn.", "r": "Luke 2:7"}, "12-20": {"v": "And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people.", "r": "Luke 2:10"}, "12-21": {"v": "But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.", "r": "Isaiah 53:5"}, "12-22": {"v": "And the glory of the LORD shall be revealed, and all flesh shall see it together: for the mouth of the LORD hath spoken it.", "r": "Isaiah 40:5"}, "12-23": {"v": "A light to lighten the Gentiles, and the glory of thy people Israel.", "r": "Luke 2:32"}, "12-24": {"v": "For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.", "r": "Isaiah 9:6"}, "12-25": {"v": "For unto you is born this day in the city of David a Saviour, which is Christ the Lord.", "r": "Luke 2:11"}, "12-26": {"v": "Glory to God in the highest, and on earth peace, good will toward men.", "r": "Luke 2:14"}, "12-27": {"v": "Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him.", "r": "Matthew 2:2"}, "12-28": {"v": "And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.", "r": "John 1:14"}, "12-29": {"v": "But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law,", "r": "Galatians 4:4"}, "12-30": {"v": "Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.", "r": "John 8:12"}, "12-31": {"v": "He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus.", "r": "Revelation 22:20"}, "2-29": {"v": "Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.", "r": "Isaiah 49:16"}};
